/* app69: Gap fills from the 2026-10-31 coverage audit — seven desks an elite mortgage + real-estate brokerage runs that VANESSA had no page for:
   Insurance Desk (HOI / flood / CA FAIR Plan + DIC quote-fail rescue, binder + mortgagee clause, payment-shock math), Vendor & Partner Management
   (categories, SLAs, W-9/E&O/SOC 2/AIR/RESPA flags, 1-5 scorecard, incidents, annual review), Compliance Management System (policy inventory,
   testing calendar, complaint clocks, incident response + notification clocks, training log, pricing-exception log), Business Continuity
   (critical functions + RTO, scenario playbooks, system inventory, tabletop log, one-click pipeline hand-off memo from live files + locks),
   Buyer-Broker Agreements post-NAR / CA AB 2992 (expirations, comp agreed vs offered, shortfall), HOA & Condo Review Desk (eligibility math),
   Quarterly Business Review (pull-through, cost per loan, margin, QoQ). Each page: forms persisted in store, checklists, Board hand-offs,
   seat, runbook, coverage row, agent tool. All top-level names are prefixed gp/GP_. */
const gpGet=(k,d)=>store.get(k,d===undefined?[]:d);const gpSet=(k,v)=>store.set(k,v);const gpId=()=>"g"+Date.now().toString(36)+Math.floor(Math.random()*999);
const gpDay=d=>d?Math.round((new Date(d+"T12:00:00")-Date.now())/864e5):null;const gpMoney=n=>"$"+Math.round(+n||0).toLocaleString();const gpToday=()=>new Date().toISOString().slice(0,10);
const gpAddDays=(d,n)=>{const x=new Date((d||gpToday())+"T12:00:00");x.setDate(x.getDate()+n);return x.toISOString().slice(0,10)};
const gpCard=(t,detail,owner,lane,dueDays)=>{if(typeof boardAdd!=="function")return toast("Board not loaded");boardAdd({t,detail,owner,lane:lane||"ISA / EA",src:"app69",due:dueDays?new Date(Date.now()+dueDays*864e5).toISOString().slice(0,10):""});toast("→ Board: "+t)};
const gpKpis=K=>`<div class="grid g${Math.min(6,K.length)}">${K.map(k=>`<div class="card kpi"><div class="k">${esc(k[0])}</div><div class="v">${esc(String(k[1]))}</div>${k[2]?`<div class="d" style="color:${k[3]||"var(--mut)"}">${esc(k[2])}</div>`:""}</div>`).join("")}</div>`;
const gpBadge=(t,c)=>`<span class="sm" style="background:${c}22;color:${c};border-radius:10px;padding:1px 8px;white-space:nowrap">${esc(t)}</span>`;
const gpFlag=(ok,t)=>`<span style="color:${ok?"var(--good)":"var(--bad)"}">${ok?"✓":"✗"} ${esc(t)}</span>`;
/* generic register: fields [id,label,type|options[],style]; cols [label,fn(row)]; actions [label,fn(row,rows)]; kpis fn(rows) */
function gpForm(p,F){return`<div class="row" style="flex-wrap:wrap;gap:6px;margin-top:6px">${F.map(f=>Array.isArray(f[2])?`<select id="${p}_${f[0]}" title="${esc(f[1])}" style="${f[3]||""}">${f[2].map(o=>`<option>${esc(o)}</option>`).join("")}</select>`:f[2]==="check"?`<label class="sm"><input type="checkbox" id="${p}_${f[0]}"> ${esc(f[1])}</label>`:`<input id="${p}_${f[0]}" type="${f[2]||"text"}" placeholder="${esc(f[1])}" title="${esc(f[1])}" style="${f[3]||(f[2]==="date"?"width:auto":"")}">`).join("")}<button class="btn sm" id="${p}_add">Add</button></div>`}
function gpRead(p,F){const o={id:gpId(),ts:Date.now()};F.forEach(f=>{const el=$("#"+p+"_"+f[0]);o[f[0]]=!el?"":f[2]==="check"?el.checked:el.value.trim()});return o}
function gpRegHtml(R){const rows=gpGet(R.key);return`${R.kpis?gpKpis(R.kpis(rows)):""}<div class="card"><b>${esc(R.title)}</b> <span class="sm mut">${esc(R.hint||"")}</span>${gpForm(R.key,R.fields)}${rows.length?`<div style="overflow:auto;margin-top:8px"><table class="sm"><tr>${R.cols.map(c=>`<th>${esc(c[0])}</th>`).join("")}<th></th></tr>${rows.map((r,i)=>`<tr>${R.cols.map(c=>`<td>${c[1](r)}</td>`).join("")}<td style="white-space:nowrap">${(R.actions||[]).map((a,j)=>`<button class="btn ghost sm gp_act" data-k="${R.key}" data-i="${i}" data-j="${j}">${esc(a[0])}</button>`).join(" ")} <button class="btn ghost sm gp_del" data-k="${R.key}" data-i="${i}" title="Delete">✕</button></td></tr>`).join("")}</table></div>`:'<p class="sm mut">Nothing logged yet.</p>'}${R.foot?`<p class="sm mut">${R.foot}</p>`:""}</div>`}
function gpRegMount(R,redraw){const add=$("#"+R.key+"_add");if(add)add.onclick=()=>{const o=gpRead(R.key,R.fields);if(!o[R.fields[0][0]])return toast("Enter "+R.fields[0][1]);if(R.prep)R.prep(o);const rows=gpGet(R.key);rows.unshift(o);gpSet(R.key,rows);toast("Saved");redraw()};
 $$(`.gp_del[data-k="${R.key}"]`).forEach(b=>b.onclick=()=>{if(!confirm("Delete this row?"))return;const rows=gpGet(R.key);rows.splice(+b.dataset.i,1);gpSet(R.key,rows);redraw()});
 $$(`.gp_act[data-k="${R.key}"]`).forEach(b=>b.onclick=()=>{const rows=gpGet(R.key);R.actions[+b.dataset.j][1](rows[+b.dataset.i],rows);gpSet(R.key,rows);redraw()})}
const gpCycle=(statuses,field="st")=>["Next status",r=>{r[field]=statuses[(statuses.indexOf(r[field])+1)%statuses.length]}];
/* persisted checklist */
function gpCheckHtml(key,items,title){const S=gpGet(key,{});return`<div class="card"><b>${esc(title)}</b> <span class="sm mut">${items.filter((x,i)=>S[i]).length}/${items.length}</span>${items.map((t,i)=>`<div class="sm"><label><input type="checkbox" class="gp_ck" data-k="${key}" data-i="${i}"${S[i]?" checked":""}> ${esc(t)}</label></div>`).join("")}</div>`}
function gpCheckMount(){$$(".gp_ck").forEach(c=>c.onchange=()=>{const S=gpGet(c.dataset.k,{});S[c.dataset.i]=c.checked;gpSet(c.dataset.k,S)})}
/* tabbed page builder: tabs [key,label,html(),mount(redraw)] */
function gpPage(id,icon,title,sub,color,tabs){let cur=tabs[0][0];const render=()=>{const v=$("#gp_"+id);if(!v)return;const T=tabs.find(t=>t[0]===cur)||tabs[0];$$(`.gp_tab[data-p="${id}"]`).forEach(b=>b.classList.toggle("on",b.dataset.t===T[0]));v.innerHTML=T[2]();try{gpCheckMount();if(T[3])T[3](render)}catch(e){console.error(e)}};
 PAGE[id]={html:()=>`<div class="card" style="border-left:4px solid ${color}"><h3 style="margin:0">${icon} ${esc(title)} <span class="sub">${esc(sub)}</span></h3><div class="row" style="gap:6px;flex-wrap:wrap;margin-top:8px">${tabs.map(t=>`<button class="btn ghost sm gp_tab" data-p="${id}" data-t="${t[0]}">${esc(t[1])}</button>`).join("")}</div></div><div id="gp_${id}"></div>`,mount(){$$(`.gp_tab[data-p="${id}"]`).forEach(b=>b.onclick=()=>{cur=b.dataset.t;render()});render()}}}
/* registration in the house style: nav (guarded), title, search route, seat, runbook, coverage row, tools */
function gpRegister(o){const G=PAGES.find(p=>p[0]===o.group)||PAGES.find(p=>p[0]==="Operate");if(G&&!G[1].some(x=>x[0]===o.id)){const i=G[1].findIndex(x=>x[0]===o.after);G[1].splice(i>=0?i+1:G[1].length,0,[o.id,o.label])}
 if(typeof TITLES!=="undefined")TITLES[o.id]=o.label;if(typeof SEARCH_ROUTES!=="undefined"&&o.route)SEARCH_ROUTES.unshift([o.route,{hash:o.id}]);
 if(typeof AI_SEATS!=="undefined"&&o.seat&&!AI_SEATS.some(s=>s.n===o.seat.n))AI_SEATS.push(Object.assign({a:"VANESSA › "+o.label.replace(/^\S+\s/,""),t:"ops"},o.seat));
 if(typeof RB!=="undefined"&&o.rb&&!RB.some(r=>r.k===o.rb.k))RB.push(Object.assign({inputs:["Live dashboard data"],outputs:["Owned Board cards","Drafts for Steven's review"],conn:[],fail:[]},o.rb));
 if(typeof CV_PROCS!=="undefined"){if(o.cvPatch){const p=CV_PROCS.find(x=>o.cvPatch[0].test(x[1]));if(p&&!p[2].split(",").includes(o.id)){p[2]+=","+o.id;if(o.cvPatch[1])p[6]=o.cvPatch[1]}}if(o.cv&&!CV_PROCS.some(x=>x[1]===o.cv[1]))CV_PROCS.push(o.cv)}
 if(typeof PB_TOOLS==="function"&&o.tools){const t0=PB_TOOLS;PB_TOOLS=()=>[...t0(),...o.tools]}}
