function gpCmsStatus(){const P=gpGet("gp_cms_pol",{}),T=gpGet("gp_cms_test",{});const pol=GP_POL.filter((p,i)=>(P[i]||{}).ok).length;const over=GP_TESTS.filter((t,i)=>{const due=gpTestDue(t[1],(T[i]||{}).d);return!due||gpDay(due)<0}).length;const cmp=gpGet("gp_cmp"),inc=gpGet("gp_inc");return{policiesWritten:pol,policiesTotal:GP_POL.length,testsOverdueOrNeverRun:over,testsTotal:GP_TESTS.length,openComplaints:cmp.filter(r=>!r.res).length,unacknowledgedComplaints:cmp.filter(r=>!r.ack).length,fairLendingFlags:cmp.filter(r=>r.fl).length,openIncidents:inc.filter(r=>!r.notified).length,ftcNotifiable:inc.filter(r=>+r.rec>=500&&!r.enc&&!r.notified).length,pricingExceptionsQtr:gpGet("gp_px").filter(r=>Date.now()-r.ts<91*864e5).length}}
