function gpHoaReview(r){if(r.loan==="FHA")return r.fha?"FHA: approved project":"FHA: needs approval or Single-Unit Approval";if(r.loan==="VA")return r.va?"VA: approved condo":"VA: condo approval required (lender submits)";if(r.loan==="Non-QM")return"Lender project review";if(/PUD|Site/.test(r.type))return"PUD: no project review (attached PUD: insurance only)";const ltv=+r.ltv||0;const lim=r.occ==="Primary"?90:r.occ==="Second home"?75:75;return ltv&&ltv<=lim?`Limited review (≤${lim}% LTV)`:`Full review (> ${lim}% LTV ${r.occ})`}
function gpHoaFlags(r){const F=[];const full=/Full|approval|Lender/.test(gpHoaReview(r));const inv=r.occ==="Investment";if(!/PUD/.test(r.type)){if(full||inv)F.push([+r.oo>=50||(!inv&&+r.oo>0),"owner-occupancy "+(r.oo||"?")+"% (≥50% for investment / full review)"]);F.push([+r.delq<=15,"60+ day delinquencies "+(r.delq||"0")+"% (≤15%)"]);F.push([+r.res>=10,"reserves "+(r.res||"0")+"% of budget (≥10%)"]);F.push([+r.comm<=35,"commercial space "+(r.comm||"0")+"% (≤35%)"]);F.push([+r.single<=(+r.units>20?20:+r.units>=5?25:50),"single-entity "+(r.single||"0")+"% (20% >20 units / 25% 5-20 / 2 units ≤4)"]);F.push([!r.lit,"no structural / safety litigation"]);F.push([!r.sa,"no special assessment / significant deferred maintenance (post-Surfside 'unavailable' list)"]);F.push([!!r.master,"master policy 100% replacement cost + fidelity/crime"+(+r.units>20?" (required >20 units)":"")]);F.push([!!r.ho6,"HO-6 walls-in (≈20% of appraised value unless all-in master)"])}else F.push([!!r.master||!/attached/i.test(r.n),"attached PUD: master/HOA insurance evidence"]);if(/Condotel|Co-op/.test(r.type))F.push([false,"condotel / co-op — non-warrantable: non-QM / portfolio lender"]);return F}
