if(typeof STP_RUN!=="undefined"){const h0=STP_RUN.hoi,c0=STP_RUN.condo;STP_RUN.hoi=f=>{const r=h0?h0(f):"";const I=gpGet("gp_ins");if(!I.some(x=>x.n===f.n)){I.unshift({id:gpId(),ts:Date.now(),n:f.n,st:"Quote requested",state:"CA",prop:"SFR",risk:"Standard",close:f.close||"",binder:false,clause:false,flood:false});gpSet("gp_ins",I)}return(r?r+"; ":"")+"Insurance Desk row opened"};STP_RUN.condo=f=>{const r=c0?c0(f):"";const H=gpGet("gp_hoa");if(!H.some(x=>x.n===f.n)){H.unshift({id:gpId(),ts:Date.now(),n:f.n,type:"Condo",loan:/FHA/i.test(f.loan||"")?"FHA":/VA/i.test(f.loan||"")?"VA":"Conventional",occ:"Primary",ltv:""});gpSet("gp_hoa",H)}return(r?r+"; ":"")+"HOA Desk project opened"}}
